const { getDatabase } = require('../_db');
const { currentUser } = require('./_auth');
module.exports = async function handler(req,res){if(req.method!=='POST')return res.status(405).json({error:'Método não permitido'});const user=currentUser(req);if(!user)return res.status(401).json({error:'Sessão expirada.'});try{const {atendimentoId,atendenteId}=req.body||{};if(!atendimentoId)return res.status(400).json({error:'Atendimento não informado.'});const alvo=atendenteId||user.id;const sql=getDatabase();const rows=await sql`UPDATE atendimentos SET atendente_id=${alvo},atualizado_em=NOW() WHERE id=${atendimentoId} AND (atendente_id IS NULL OR atendente_id=${user.id} OR ${user.perfil}='ADMINISTRADOR') RETURNING id,atendente_id`;if(!rows[0])return res.status(409).json({error:'Este atendimento já está com outro atendente.'});return res.status(200).json({ok:true,atendimento:rows[0]})}catch(error){console.error(error);return res.status(500).json({error:'Não foi possível assumir ou transferir o atendimento.'})}};
